     1	package org.springframework.samples.petclinic.model;
     2	
     3	/**
     4	 * The single definition of the <em>Luhn check digit</em> computed over the digits of a
     5	 * customer code. Non-digit characters (separators, letters) are ignored; the remaining
     6	 * digits are folded right-to-left with the rightmost digit doubled, and the check digit is
     7	 * the amount that rounds the running sum up to the next multiple of ten.
     8	 *
     9	 * <p>Returned by the response mapper alongside the customer code so a caller can verify the
    10	 * code was transcribed correctly.
    11	 */
    12	public final class CheckDigit {
    13	
    14	    private CheckDigit() {
    15	    }
    16	
    17	    /** The Luhn check digit (0-9) over the digit characters of {@code code}. */
    18	    public static int luhn(String code) {
    19	        int sum = 0;
    20	        boolean dbl = true;
    21	        for (int i = code.length() - 1; i >= 0; i--) {
    22	            char c = code.charAt(i);
    23	            if (c < '0' || c > '9') {
    24	                continue;
    25	            }
    26	            int d = c - '0';
    27	            if (dbl) {
    28	                d *= 2;
    29	                if (d > 9) {
    30	                    d -= 9;
    31	                }
    32	            }
    33	            sum += d;
    34	            dbl = !dbl;
    35	        }
    36	        return (10 - (sum % 10)) % 10;
    37	    }
    38	}
