     3	import java.util.Map;
     4	import java.util.regex.Pattern;
     5	
     6	/**
     7	 * Pinned locality reference data. A region is derived by postcode range first, falling back
     8	 * to the city-to-region table; anything that matches neither resolves to {@link #UNKNOWN}.
     9	 */
    10	public final class Locality {
    11	
    12	    /** The locality returned for a city that is not in the table. */
    13	    public static final String UNKNOWN = "UNKNOWN";
    14	
    15	    /** A well-formed 4-digit postcode. */
    16	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
    17	
    18	    /** City -> canonical region. */
    19	    private static final Map<String, String> CITY_REGION = Map.of(
    20	            "Sydney", "NSW",
    21	            "Melbourne", "VIC",
    22	            "Brisbane", "QLD");
    23	
    24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
    25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
    26	            "NSW", new int[] {2000, 2099},
    27	            "VIC", new int[] {3000, 3099},
    28	            "QLD", new int[] {4000, 4099});
    29	
    30	    private Locality() {
    31	    }
    32	
    33	    /**
    34	     * Derive the canonical region, preferring the postcode. The postcode's range decides the
    35	     * region when it falls in a known range; otherwise (postcode absent or unrecognised) the
    36	     * city-to-region table decides.
    37	     *
    38	     * @param city     the owner's city (may be {@code null})
    39	     * @param postcode the owner's postcode (may be {@code null} or non-numeric)
    40	     * @return the canonical region string, or {@link #UNKNOWN} when neither postcode nor city is known
    41	     */
    42	    public static String regionFor(String city, String postcode) {
    43	        String byPostcode = regionForPostcode(postcode);
    44	        return byPostcode != null ? byPostcode : regionFor(city);
    45	    }
    46	
    47	    /**
    48	     * Derive the canonical region for the given city.
    49	     *
    50	     * @param city the owner's city (may be {@code null})
    51	     * @return the canonical region string, or {@link #UNKNOWN} when the city is not in the table
    52	     */
    53	    public static String regionFor(String city) {
    54	        return CITY_REGION.getOrDefault(city, UNKNOWN);
    55	    }
    56	
    57	    /**
    58	     * The region whose pinned postcode range contains the given postcode.
    59	     *
    60	     * @param postcode the owner's postcode (may be {@code null} or non-numeric)
    61	     * @return the matching region, or {@code null} when the postcode is absent, non-numeric or in no range
    62	     */
    63	    private static String regionForPostcode(String postcode) {
    64	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
    65	            return null;
    66	        }
    67	        int value = Integer.parseInt(postcode);
    68	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
    69	            int[] range = entry.getValue();
    70	            if (value >= range[0] && value <= range[1]) {
    71	                return entry.getKey();
    72	            }
    73	        }
    74	        return null;
    75	    }
    76	
    77	    /**
    78	     * Whether the given 4-digit postcode is permitted for the given city. A city whose
    79	     * region has a pinned postcode range accepts only postcodes within that (inclusive)
    80	     * range; a city with no known region accepts any postcode.
    81	     *
    82	     * @param city     the owner's city (may be {@code null})
    83	     * @param postcode the numeric value of a 4-digit postcode
    84	     * @return {@code true} when the postcode is allowed for the city's region
    85	     */
    86	    public static boolean postcodeAllowedForCity(String city, int postcode) {
    87	        int[] range = REGION_POSTCODES.get(regionFor(city));
    88	        return range == null || (postcode >= range[0] && postcode <= range[1]);
    89	    }
    90	}
