     9	/**
    10	 * Assigns the owner's customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is
    11	 * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters
    12	 * of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than
    13	 * the number of owners already in that city. Runs before the owner is saved and mutates the
    14	 * built {@link Owner} in place.
    15	 */
    16	public class AssignOwnerCustomerCode {
    17	
    18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
    19	        String cityPrefix = prefix(owner.getCity());
    20	        String lastNamePrefix = prefix(owner.getLastName());
    21	        int sequence = OwnerCities.size(ownerRepository.findAll(), owner.getCity()) + 1;
    22	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence));
    23	    }
    24	
    25	    private static String prefix(String value) {
    26	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
    27	    }
    28	}
