    12	/**
    13	 * The single definition of what a "household" is: owners sharing the same last name and
    14	 * address, compared case-insensitively with runs of whitespace collapsed to a single
    15	 * space. Shared by {@link RejectDuplicateOwnerHousehold} (which forbids an unopted
    16	 * duplicate) and {@link AssignOwnerHousehold} (which links opted-in members), so both
    17	 * decide membership identically.
    18	 */
    19	final class OwnerHouseholds {
    20	
    21	    private static final int ID_HEX_LENGTH = 12;
    22	
    23	    private OwnerHouseholds() {
    24	    }
    25	
    26	    /** The existing owners that share the household identified by {@code lastName} and {@code address}. */
    27	    static List<Owner> members(Iterable<Owner> owners, String lastName, String address) {
    28	        String canonicalLastName = canonical(lastName);
    29	        String canonicalAddress = canonical(address);
    30	        List<Owner> members = new ArrayList<>();
    31	        for (Owner existing : owners) {
    32	            if (canonicalLastName.equals(canonical(existing.getLastName()))
    33	                    && canonicalAddress.equals(canonical(existing.getAddress()))) {
    34	                members.add(existing);
    35	            }
    36	        }
    37	        return members;
    38	    }
    39	
    40	    /**
    41	     * The household id an owner with this {@code lastName} and {@code address} would be
    42	     * assigned: the shared id when it opts in ({@code sharesHousehold}) and existing owners
    43	     * already form that household, otherwise {@code null} (it stands alone). Shared by
    44	     * {@link RejectDuplicateOwnerIdentity} (to derive the would-be identity key) and
    45	     * {@link AssignOwnerHousehold} (which then links the members), so both agree.
    46	     */
    47	    static String assignedId(boolean sharesHousehold, String lastName, String address, Iterable<Owner> owners) {
    48	        if (!sharesHousehold || members(owners, lastName, address).isEmpty()) {
    49	            return null;
    50	        }
    51	        return householdId(lastName, address);
    52	    }
    53	
    54	    /**
    55	     * A stable identifier for the household: derived from the canonical last name and
    56	     * address, so every member computes the same value regardless of creation order.
    57	     */
    58	    static String householdId(String lastName, String address) {
    59	        String key = canonical(lastName) + "�" + canonical(address);
    60	        try {
    61	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
    62	            StringBuilder hex = new StringBuilder(ID_HEX_LENGTH);
    63	            for (int i = 0; hex.length() < ID_HEX_LENGTH; i++) {
    64	                hex.append(String.format("%02X", digest[i] & 0xFF));
    65	            }
    66	            return hex.substring(0, ID_HEX_LENGTH);
    67	        } catch (NoSuchAlgorithmException ex) {
    68	            throw new IllegalStateException("SHA-256 is required to derive a household id", ex);
    69	        }
    70	    }
    71	
    72	    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
    73	    private static String canonical(String value) {
    74	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    75	    }
    76	}

